import re

def count_distinct_characters(string: str) -> int:
    # Extract only alphabetic characters from the input string
    alphabetic_chars = re.findall('[a-zA-Z]', string)

    # Convert all characters to lowercase to ignore case
    lowercase_chars = [char.lower() for char in alphabetic_chars]

    # Count the number of distinct characters in the string
    distinct_chars = set(lowercase_chars)

    return len(distinct_chars)

